// useUserPreferences.ts - Simulates fetching user preferences from Context Engine
import { useState, useEffect } from 'react';

export interface UserPreferences {
  textSize: 'normal' | 'large' | 'extra-large';
  contrast: 'normal' | 'high';
  buttonSize: 'standard' | 'large' | 'extra-large';
}

export interface UserProfile {
  userName: string;
  age: number;
  cognitiveComfort: string;
}

export interface ContextResponse {
  userProfile: UserProfile;
  preferences: UserPreferences;
  dailyInsight: string;
  vitals: {
    heartRate: number;
    sleepScore: number;
    lastUpdated: string;
  };
  upcomingEvents: Array<{
    id: string;
    title: string;
    time: string;
    type: 'appointment' | 'medication' | 'social';
  }>;
  emergencyContacts: Array<{
    id: string;
    name: string;
    relation: string;
    phone: string;
  }>;
}

// Mock data simulating backend Context Engine response
const MOCK_CONTEXT_RESPONSE: ContextResponse = {
  userProfile: {
    userName: 'Grandpa Joe',
    age: 78,
    cognitiveComfort: 'intermediate'
  },
  preferences: {
    textSize: 'large',
    contrast: 'high',
    buttonSize: 'large'
  },
  dailyInsight: "It's a sunny Tuesday, Grandpa Joe. Remember to drink water after your walk!",
  vitals: {
    heartRate: 72,
    sleepScore: 85,
    lastUpdated: '2 hours ago'
  },
  upcomingEvents: [
    {
      id: '1',
      title: 'Dr. Smith appointment',
      time: 'Today at 2:00 PM',
      type: 'appointment'
    },
    {
      id: '2',
      title: 'Take evening medication',
      time: 'Today at 6:00 PM',
      type: 'medication'
    },
    {
      id: '3',
      title: 'Call with Sarah',
      time: 'Tomorrow at 10:00 AM',
      type: 'social'
    }
  ],
  emergencyContacts: [
    {
      id: '1',
      name: 'Dr. Sarah Johnson',
      relation: 'Primary Doctor',
      phone: '+1-555-0101'
    },
    {
      id: '2',
      name: 'John Smith',
      relation: 'Son',
      phone: '+1-555-0102'
    },
    {
      id: '3',
      name: 'Mary Williams',
      relation: 'Daughter',
      phone: '+1-555-0103'
    }
  ]
};

/**
 * Custom hook that simulates fetching user preferences and context from backend
 * In production, this would make an API call to the Context Retrieval Engine
 */
export const useUserPreferences = (): {
  contextData: ContextResponse | null;
  isLoading: boolean;
  error: string | null;
} => {
  const [contextData, setContextData] = useState<ContextResponse | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate API call delay
    const fetchContextData = async () => {
      try {
        setIsLoading(true);

        // Simulate network delay
        await new Promise(resolve => setTimeout(resolve, 500));

        // In production, this would be:
        // const response = await fetch('http://localhost:8082/api/context');
        // const data = await response.json();

        setContextData(MOCK_CONTEXT_RESPONSE);
        setError(null);
      } catch (err) {
        setError('Failed to load user context');
        console.error('Context fetch error:', err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchContextData();
  }, []);

  return { contextData, isLoading, error };
};

/**
 * Helper function to get Tailwind classes based on preferences
 */
export const getPreferenceClasses = (preferences: UserPreferences | undefined) => {
  if (!preferences) {
    return {
      text: {
        base: 'text-base',
        lg: 'text-lg',
        xl: 'text-xl',
        '2xl': 'text-2xl',
        '3xl': 'text-3xl'
      },
      button: {
        height: 'h-12',
        padding: 'px-6 py-3',
        text: 'text-base'
      },
      container: {
        gap: 'gap-4',
        padding: 'p-4'
      },
      border: 'border border-gray-200',
      shadow: 'shadow-md'
    };
  }

  // Text size classes
  const textClasses = {
    normal: {
      base: 'text-base',
      lg: 'text-lg',
      xl: 'text-xl',
      '2xl': 'text-2xl',
      '3xl': 'text-3xl'
    },
    large: {
      base: 'text-lg',
      lg: 'text-xl',
      xl: 'text-2xl',
      '2xl': 'text-3xl',
      '3xl': 'text-4xl'
    },
    'extra-large': {
      base: 'text-xl',
      lg: 'text-2xl',
      xl: 'text-3xl',
      '2xl': 'text-4xl',
      '3xl': 'text-5xl'
    }
  };

  // Button size classes
  const buttonClasses = {
    standard: {
      height: 'h-12',
      padding: 'px-6 py-3',
      text: 'text-base'
    },
    large: {
      height: 'h-16',
      padding: 'px-8 py-4',
      text: 'text-lg'
    },
    'extra-large': {
      height: 'h-20',
      padding: 'px-10 py-6',
      text: 'text-xl'
    }
  };

  // Container spacing
  const containerClasses = {
    normal: {
      gap: 'gap-4',
      padding: 'p-4'
    },
    large: {
      gap: 'gap-6',
      padding: 'p-6'
    },
    'extra-large': {
      gap: 'gap-8',
      padding: 'p-8'
    }
  };

  // Contrast-based styling
  const contrastClasses = {
    normal: {
      border: 'border border-gray-200',
      shadow: 'shadow-md',
      bg: 'bg-white',
      text: 'text-gray-700',
      hover: 'hover:bg-gray-50'
    },
    high: {
      border: 'border-2 border-black',
      shadow: '',
      bg: 'bg-white',
      text: 'text-black',
      hover: 'hover:bg-gray-100'
    }
  };

  return {
    text: textClasses[preferences.textSize],
    button: buttonClasses[preferences.buttonSize],
    container: containerClasses[preferences.buttonSize === 'extra-large' ? 'extra-large' : preferences.buttonSize === 'large' ? 'large' : 'normal'],
    ...contrastClasses[preferences.contrast]
  };
};
